mapper.select:
select 
from (
    select 
    from PAY_REFUND_DETAIL
    where REFUND_STATUS = 'PROCESSING'
      and TXN_DATE >= #{txnDateFrom,jdbcType=VARCHAR}
      and NVL(LAST_REQUEST_TIME, CREATE_TIME)
          < SYSTIMESTAMP - NUMTODSINTERVAL(#{staleMinutes,jdbcType=INTEGER}, 'MINUTE')
      and (NEXT_REQUEST_TIME is null or NEXT_REQUEST_TIME <= SYSTIMESTAMP)
    order by NVL(LAST_REQUEST_TIME, CREATE_TIME)
)
where ROWNUM <= #{limit,jdbcType=INTEGER}

mapper.update:
UPDATE PAY_REFUND_DETAIL
SET NEXT_REQUEST_TIME = SYSTIMESTAMP + NUMTODSINTERVAL(#{delaySeconds,jdbcType=INTEGER}, 'SECOND'),
    UPDATE_TIME = SYSTIMESTAMP
WHERE REFUND_ORDER_NO = #{refundOrderNo,jdbcType=VARCHAR}
  AND TXN_DATE = #{txnDate,jdbcType=VARCHAR}
  AND REFUND_STATUS = 'PROCESSING'

mapper.select:
select ORDER_NO
from (
    select ORDER_NO
    from (
        select distinct R.ORDER_NO as ORDER_NO
        from PAY_REFUND_DETAIL R
        where R.TXN_DATE >= #{txnDateFrom,jdbcType=VARCHAR}
          and R.REFUND_STATUS = 'SUCCESS'
    ) C
    where exists (
        select 1
        from PAY_TXN_DETAIL P
        where P.ORDER_NO = C.ORDER_NO
          and NVL(P.REFUND_AMOUNT, 0) <> (
              select NVL(SUM(R2.REFUND_AMOUNT), 0)
              from PAY_REFUND_DETAIL R2
              where R2.ORDER_NO = C.ORDER_NO
                and R2.REFUND_STATUS = 'SUCCESS')
    )
    order by ORDER_NO
)
where ROWNUM <= #{limit,jdbcType=INTEGER}

select ORDER_NO
from (
    select distinct R.ORDER_NO as ORDER_NO
    from PAY_REFUND_DETAIL R
    where R.TXN_DATE >= #{txnDateFrom,jdbcType=VARCHAR}
      and R.REFUND_STATUS = 'SUCCESS'
      and not exists (
          select 1
          from PAY_TXN_DETAIL P
          where P.ORDER_NO = R.ORDER_NO)
    order by ORDER_NO
)
where ROWNUM <= #{limit,jdbcType=INTEGER}
